internal class GUPBasePriceCalcItem extends GUPBasePriceCalcBase
{
    private GUPItemBasePriceCalcTable       basePriceCalcTable;
    private GUPItemBasePriceCalcTrans       basePriceCalcTrans;

    private GUPBasePriceCalcPriceCalcId     priceCalcId;
    private GUPBasePriceVersionId           basePriceVersionId;
    private GUPBasePriceVersion             basePriceVersion;
    private InventSiteId                    siteId;
    private NoYes                           purchPriceTransfer;
    private NoYes                           salesPriceTransfer;
    private NoYes                           costPriceTransfer;
    private CurrencyCode                    curCurrency;

    private GUPBasePriceRawData             basePriceRawData;
    private InventDim                       inventDimCriteriaForCalcItem;
    private InventDimParm                   productDims;

    private GUPItemBasePriceCalcTransDetail itemBasePriceCalcTransDetail;

}

