public void calc()
{
    ListEnumerator  listEnumerator;

    try
    {
        setPrefix(GUPBasePriceCalcItem::description());

        if (inventDimId != InventDim::inventDimIdBlank())
        {
            setPrefix(strFmt('%1 (%2)', strFmt("@SYS24300", itemId), inventDim.preFixValue()));
        }
        else
        {
            setPrefix(strFmt("@SYS24300", itemId));
        }

        if (!this.validate())
        {
            throw Exception::Error;
        }

        if (!this.existingVendPriceList(this.key1(), this.parmSiteId()))
        {
            return;
        }

        this.init();

        this.setProgressTotals();

        this.recalcBasePrice();

        this.insertBasePriceCalcTable();
    }
    catch (Exception::Error)
    {
        throw error("@SYS19457");
    }

}

void recalcBasePrice()
{
    this.setLineNum();

    this.updateProgress();

    this.calcPriceForPriceType();

    this.markFinalPrice();

    this.insertBasePriceCalcTrans();
}

public void init()
{
    this.initParameters();

    basePriceVersion = GUPBasePriceVersion::find(basePriceVersionId);

    inventDimCriteriaForCalcItem = this.parmInventDim();
    productDims.initFromInventDim(inventDimCriteriaForCalcItem, InventDim::dimProductDimFieldList());
}

protected void initParameters()
{
    NumberSeq   numberSeq;

    super();

    if (!priceCalcId)
    {
        if (basePriceCalcTable.PriceCalcId)
        {
            priceCalcId = basePriceCalcTable.PriceCalcId;
        }
        else
        {
            numberSeq   = NumberSeq::newGetNum(BOMParameters::numRefPriceCalcId());
            priceCalcId = numberSeq.num();
        }
    }

    curCurrency = Ledger::accountingCurrency(CompanyInfo::current());

    this.initProgressBar();
    this.incProgressTotals();
}

private boolean existingVendPriceList(
    ItemId _itemId,
    InventSiteId _inventSiteId)
{
    GUPVendListPriceView    vendListPrices;

    InventDim       inventDimSite;
    InventDim       inventDimCriteria;
    InventDimParm   inventDimParm;

    inventDimCriteria.InventSiteId  = _inventSiteId;
    inventDimParm.inventSiteIdFlag  = NoYes::Yes;

    select firstonly vendListPrices
        where vendListPrices.ItemNum == _itemId
        #InventDimJoin(vendListPrices.inventDimId, inventDimSite, inventDimCriteria, inventDimParm);

    return vendListPrices.RecId;
}

private void calcPriceForPriceType()
{
    GUPVendListPriceTmp     vendListPriceTmp;
    InventDim               inventDimCalcItem;

    vendListPriceTmp = basePriceRawData.paramVendListPriceTmp();

    // Per item calculation task, we only have site and product variants dimensions if necessary
    while select vendListPriceTmp
        order by vendListPriceTmp.AccountCode, vendListPriceTmp.AccountNum
        where  vendListPriceTmp.ItemId == this.key1()
        #InventDimExistsJoin(vendListPriceTmp.InventDimId, inventDimCalcItem, inventDimCriteriaForCalcItem, productDims)
    {
        if (this.parmPurchPriceTransfer())
        {
            this.calcTmpBasePricePerPriceType(vendListPriceTmp, GUPBasePriceType::BasePricePurchase);
        }

        if (this.parmSalesPriceTransfer())
        {
            this.calcTmpBasePricePerPriceType(vendListPriceTmp, GUPBasePriceType::BasePriceSales);
        }

        if (this.parmCostPriceTransfer())
        {
            this.calcTmpBasePricePerPriceType(vendListPriceTmp, GUPBasePriceType::BasePriceInventoryCost);
        }
    }
}

private void calcTmpBasePricePerPriceType(GUPVendListPriceTmp _vendListPriceTmp, GUPBasePriceType _basePriceType)
{
    GUPVendListPriceSplitDateTmp vendListPriceSplitDateTmp;
    date fromDate;
    date toDate;

    vendListPriceSplitDateTmp = basePriceRawData.paramVendListPriceSplitDateTmp();

    fromDate = _vendListPriceTmp.FromDate;
    while select vendListPriceSplitDateTmp 
        order by vendListPriceSplitDateTmp.IntermediumDate asc
        where vendListPriceSplitDateTmp.VendListPriceTmpRecId == _vendListPriceTmp.RecId
    {
        // Skip duplicated InterMediumDate produced by price terms with same FromDate
        if (vendListPriceSplitDateTmp.IntermediumDate >= fromDate)
        {
            this.calcTmpBasePricePerPeriod(_vendListPriceTmp, _basePriceType,  fromDate, vendListPriceSplitDateTmp.IntermediumDate);
            fromDate = vendListPriceSplitDateTmp.IntermediumDate + 1;
        }
    }
    this.calcTmpBasePricePerPeriod(_vendListPriceTmp, _basePriceType, fromDate, _vendListPriceTmp.ToDate);
}

private void calcTmpBasePricePerPeriod(GUPVendListPriceTmp _vendListPriceTmp, GUPBasePriceType _basePriceType, FromDate _fromDate, ToDate _toDate)
{
    GUPPriceTermAgreementTmp    priceTermAgreementTmp;
    GUPVendListPriceAndPriceTermAgreementTmp vendListPriceAndPriceTermsTmp;

    InventDim       priceTermInventDim;

    GUPVendPriceAmount          defaultPrice;
    GUPBaseAmountNonMonetary    calculatedValue;
    GUPBaseAmountNonMonetary    calculatedPrice;
    LineNum                     calcTransLineNum;

    PriceConvertFactory         priceConvertFactory;
    PriceConvert                priceConvert;
    CurrencyCode                transCurrency;
    date                        fromDate;
    date                        toDate;

    priceTermAgreementTmp = basePriceRawData.paramPriceTermAgreementTmp();
    vendListPriceAndPriceTermsTmp = basePriceRawData.paramVendListPriceAndPriceTermAgreementTmp();

    defaultPrice        = _vendListPriceTmp.Amount;
    transCurrency       = _vendListPriceTmp.Currency;

    priceConvertFactory = PriceConvertFactory::newItemPrice(_vendListPriceTmp.ItemId,
                                                            _vendListPriceTmp.UnitId,
                                                             defaultPrice,
                                                             _vendListPriceTmp.PriceUnit,
                                                             _vendListPriceTmp.Markup,
                                                             1,
                                                             transCurrency);

    priceConvertFactory.parmNewCurrencyCode(curCurrency);
    priceConvertFactory.parmNewUnitId(this.getNewUnitId(_vendListPriceTmp.ItemId, _basePriceType));
    priceConvert = priceConvertFactory.priceConvert();
    defaultPrice = priceConvert.parmPrice();

    calculatedPrice = defaultPrice;
    calcTransLineNum = 1;

    while select priceTermAgreementTmp
        order by priceTermAgreementTmp.CalculationSequence
        join vendListPriceAndPriceTermsTmp
        where priceTermAgreementTmp.ValidFrom <= _fromDate
            && ((_toDate && priceTermAgreementTmp.ValidTo >= _toDate) || !priceTermAgreementTmp.ValidTo)
            && vendListPriceAndPriceTermsTmp.PriceTermAgreementTmpRecId == priceTermAgreementTmp.RecId
            && vendListPriceAndPriceTermsTmp.VendListPriceTmpRecId == _vendListPriceTmp.RecId
            && ((_basePriceType == GUPBasePriceType ::BasePricePurchase && priceTermAgreementTmp.CalculateBasePricePurchase == NoYes::Yes)  
                || (_basePriceType == GUPBasePriceType ::BasePriceSales && priceTermAgreementTmp.CalculateBasePriceSales == NoYes::Yes)         
                || (_basePriceType == GUPBasePriceType ::BasePriceInventoryCost && priceTermAgreementTmp.CalculateBasePriceInventory == NoYes::Yes))
    {
        itemBasePriceCalcTransDetail.clear();

        if (priceTermAgreementTmp.CalculateMethod == GUPPriceTermCalculateMethod::FixedAmount)
        {
            calculatedValue = priceTermAgreementTmp.Value;
            priceConvertFactory.parmUnitId(priceTermAgreementTmp.UnitId);
            priceConvertFactory.parmPrice(calculatedValue);
            priceConvert    = priceConvertFactory.priceConvert();
            calculatedValue = priceConvert.parmPrice();
        }
        else if (priceTermAgreementTmp.CalculateMethod == GUPPriceTermCalculateMethod::Percent)
        {
            if (priceTermAgreementTmp.CompoundCalculationBasis)
            {
                calculatedValue = calculatedPrice * priceTermAgreementTmp.Value/100;
            }
            else
            {
                calculatedValue = defaultPrice * priceTermAgreementTmp.Value/100;
            }
        }

        calculatedPrice =  calculatedPrice + calculatedValue;

        if (priceTermAgreementTmp.CompoundCalculationBasis && priceTermAgreementTmp.CalculateMethod == GUPPriceTermCalculateMethod::Percent)
        {
            itemBasePriceCalcTransDetail.BasePrice         = calculatedPrice - calculatedValue;
        }
        else
        {
            itemBasePriceCalcTransDetail.BasePrice         = defaultPrice;
        }

        itemBasePriceCalcTransDetail.PriceCalcId       = priceCalcId;
        itemBasePriceCalcTransDetail.LineNum           = calcTransLineNum;
        itemBasePriceCalcTransDetail.PriceType         = _basePriceType;
        itemBasePriceCalcTransDetail.AccountCode       = _vendListPriceTmp.AccountCode;
        itemBasePriceCalcTransDetail.AccountRelation   = _vendListPriceTmp.AccountNum;
        itemBasePriceCalcTransDetail.CalculateMethod   = priceTermAgreementTmp.CalculateMethod;
        itemBasePriceCalcTransDetail.PriceTerm         = priceTermAgreementTmp.Code;
        itemBasePriceCalcTransDetail.Value             = priceTermAgreementTmp.Value;
        itemBasePriceCalcTransDetail.CalculatedValue   = calculatedValue;
        itemBasePriceCalcTransDetail.CalculatedPrice   = calculatedPrice;
        itemBasePriceCalcTransDetail.FromDate          = _fromDate;
        itemBasePriceCalcTransDetail.ToDate            = _toDate;

        itemBasePriceCalcTransDetail.CompoundCalculationBasis = priceTermAgreementTmp.CompoundCalculationBasis;
        itemBasePriceCalcTransDetail.insert();
        calcTransLineNum++;
    }

    if (calcTransLineNum == 1)
    {
        itemBasePriceCalcTransDetail.PriceCalcId       = priceCalcId;
        itemBasePriceCalcTransDetail.LineNum           = calcTransLineNum;
        itemBasePriceCalcTransDetail.PriceType         = _basePriceType;
        itemBasePriceCalcTransDetail.AccountCode       = _vendListPriceTmp.AccountCode;
        itemBasePriceCalcTransDetail.AccountRelation   = _vendListPriceTmp.AccountNum;
        itemBasePriceCalcTransDetail.CalculateMethod   = GUPPriceTermCalculateMethod::FixedAmount;
        itemBasePriceCalcTransDetail.CalculatedPrice   = calculatedPrice;
        itemBasePriceCalcTransDetail.FromDate          = _fromDate;
        itemBasePriceCalcTransDetail.ToDate            = _toDate;
        itemBasePriceCalcTransDetail.BasePrice		   = calculatedPrice;

        itemBasePriceCalcTransDetail.insert();
    }
}

private UnitOfMeasureSymbol getNewUnitId(ItemId _itemId, GUPBasePriceType _priceType)
{
    UnitOfMeasureSymbol     unitOfMeasureSymbol;
    InventTable             inventTable = InventTable::find(_itemId);

    switch (_priceType)
    {
        case GUPBasePriceType::BasePriceInventoryCost :
            unitOfMeasureSymbol = inventTable.inventUnitId();
            break;

        case GUPBasePriceType::BasePricePurchase :
            unitOfMeasureSymbol = inventTable.purchUnitId();
            break;

        case GUPBasePriceType::BasePriceSales :
            unitOfMeasureSymbol = inventTable.salesUnitId();
            break;
    }

    return unitOfMeasureSymbol;
}

public static GUPBasePriceCalcItem newItem(
    GUPBasePriceRawData             _basePriceRawData,
    ItemId                          _itemId,
    InventDimId                     _inventDimId,
    GUPBasePriceCalcPriceCalcId     _priceCalcId              = '',
    TransDate                       _calcDate                 = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
    GUPBasePriceVersionId           _basePriceVersionId       = '',
    GUPCalcBasePriceVersionUpdate   _calcVersionUpdate        = GUPCalcBasePriceVersionUpdate::Overwrite,
    NoYes                           _purchPriceTransfer       = NoYes::No,
    NoYes                           _salesPriceTransfer       = NoYes::No,
    NoYes                           _costPriceTransfer        = NoYes::No)
{
    GUPBasePriceCalcItem basePriceCalcItem;
    InventDim       foundInventDim;

    basePriceCalcItem = GUPBasePriceCalcItem::construct();

    basePriceCalcItem.parmBasePriceRawData(_basePriceRawData);

    basePriceCalcItem.parmItemId(_itemId);

    foundInventDim = InventDim::find(_inventDimId);
    basePriceCalcItem.parmInventDimId(_inventDimId);
    basePriceCalcItem.parmInventDim(foundInventDim);

    if (foundInventDim)
    {
        basePriceCalcItem.parmSiteId(foundInventDim.InventSiteId);
    }

    basePriceCalcItem.parmPriceCalcId(_priceCalcId);
    basePriceCalcItem.parmCalcDate(_calcDate);
    basePriceCalcItem.parmBasePriceVersionId(_basePriceVersionId);
    basePriceCalcItem.parmPurchPriceTransfer(_purchPriceTransfer);
    basePriceCalcItem.parmSalesPriceTransfer(_salesPriceTransfer);
    basePriceCalcItem.parmCostPriceTransfer(_costPriceTransfer);

    return basePriceCalcItem;
}

public static GUPBasePriceCalcItem construct()
{
    return new GUPBasePriceCalcItem();
}

private static ClassDescription description()
{
    return "@SYS5681";
}

protected void initializeBasePriceCalcTable()
{
    basePriceCalcTable.ItemId           = this.key1();
    basePriceCalcTable.InventDimId      = this.key2();
    basePriceCalcTable.PriceCalcId      = priceCalcId;
    basePriceCalcTable.UnitId           = inventUnitId;
    basePriceCalcTable.VersionId        = basePriceVersionId;
    basePriceCalcTable.Currency         = curCurrency;
    basePriceCalcTable.PriceRule        = basePriceVersion.PriceRule;
    basePriceCalcTable.PriceBasis       = basePriceVersion.PriceBasis;
}

public void insertBasePriceCalcTable()
{
    this.initializeBasePriceCalcTable();

    if (basePriceCalcTable.RecId)
    {
        basePriceCalcTable.update();
    }
    else
    {
        basePriceCalcTable.insert();
    }
}

public void insertBasePriceCalcTrans() { GUPItemBasePriceCalcTransDetail theCheapPriceResult; GUPItemBasePriceCalcTransDetail itemBasePriceCalcTransDetailPrice;
GUPItemBasePriceCalcTrans itemBasePriceCalcTrans;
theCheapPriceResult.setTmpData(this.parmItemBasePriceCalcTransDetail()); itemBasePriceCalcTransDetailPrice.setTmpData(this.parmItemBasePriceCalcTransDetail());
while select minof(CalculatedPrice) from itemBasePriceCalcTransDetailPrice group by PriceType, FromDate where itemBasePriceCalcTransDetailPrice.FinalPrice == NoYes::Yes && itemBasePriceCalcTransDetailPrice.PriceCalcId == priceCalcId { GUPItemBasePriceCalcTransDetail itemBasePriceCalcTransDetailLocal = GUPItemBasePriceCalcTransDetail::findByFinalPrice( this.parmItemBasePriceCalcTransDetail(), itemBasePriceCalcTransDetailPrice.PriceType, itemBasePriceCalcTransDetailPrice.CalculatedPrice, priceCalcId, itemBasePriceCalcTransDetailPrice.FromDate);
insert_recordset itemBasePriceCalcTrans ( AccountCode, AccountRelation, PriceCalcId, PriceType, PriceTerm, BasePrice, CalculateMethod, Value, CalculatedValue, CalculatedPrice, CompoundCalculationBasis, FinalPrice, FromDate, ToDate) select AccountCode, AccountRelation, PriceCalcId, PriceType, PriceTerm, BasePrice, CalculateMethod, Value, CalculatedValue, CalculatedPrice, CompoundCalculationBasis, FinalPrice, FromDate, ToDate from theCheapPriceResult where theCheapPriceResult.AccountCode == itemBasePriceCalcTransDetailLocal.AccountCode && theCheapPriceResult.AccountRelation == itemBasePriceCalcTransDetailLocal.AccountRelation && theCheapPriceResult.PriceType == itemBasePriceCalcTransDetailLocal.PriceType && theCheapPriceResult.FromDate == itemBasePriceCalcTransDetailLocal.FromDate; } }

private void markFinalPrice()
{
    GUPItemBasePriceCalcTransDetail     itemBasePriceCalcTransDetailLine;

    itemBasePriceCalcTransDetailLine.setTmpData(this.parmItemBasePriceCalcTransDetail());

    ttsbegin;

    while select maxof(LineNum) from itemBasePriceCalcTransDetailLine
        group by PriceType, AccountCode, AccountRelation, FromDate
        where itemBasePriceCalcTransDetailLine.PriceCalcId == priceCalcId
    {
        GUPItemBasePriceCalcTransDetail itemBasePriceCalcTransDetailLocal;

        itemBasePriceCalcTransDetailLocal = GUPItemBasePriceCalcTransDetail::findByLineNum(
            this.parmItemBasePriceCalcTransDetail(),
            itemBasePriceCalcTransDetailLine.PriceType,
            itemBasePriceCalcTransDetailLine.AccountCode,
            itemBasePriceCalcTransDetailLine.AccountRelation,
            itemBasePriceCalcTransDetailLine.LineNum,
            priceCalcId,
            itemBasePriceCalcTransDetailLine.FromDate,
            true);

        itemBasePriceCalcTransDetailLocal.FinalPrice = NoYes::Yes;
        itemBasePriceCalcTransDetailLocal.doUpdate();
    }

    ttscommit;
}

protected KeyValue key1()
{
    return itemId;
}

protected KeyValue key2()
{
    return inventDimId;
}

